  assert.ok(result.ok);
  assert.equal(result.value.invoices.length, 1);
  assert.equal(result.value.invoices[0].number, issued1.value.number);
});

test('statement: multiple invoices with various payment states', () => {
  // Create three invoices with C-002 (standard tier, no discount)
  const inv1Result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-01-01',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.ok(inv1Result.ok);
  const issued1 = issueInvoice(inv1Result.value, []);
  assert.ok(issued1.ok);

  const inv2Result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-02-01',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.ok(inv2Result.ok);
  const issued2 = issueInvoice(inv2Result.value, [issued1.value.number]);
  assert.ok(issued2.ok);

  const inv3Result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-03-01',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.ok(inv3Result.ok);
  const issued3 = issueInvoice(inv3Result.value, [issued1.value.number, issued2.value.number]);
  assert.ok(issued3.ok);

  // Pay fully on invoice 1, partially on invoice 2, nothing on invoice 3
  // C-002 standard tier: 9500 + 1995 VAT = 11495
  const payment1 = recordPayment(issued1.value, { amount: 11495, date: '2026-01-10' });
  assert.ok(payment1.ok);

  const payment2 = recordPayment(issued2.value, { amount: 5000, date: '2026-02-10' });
  assert.ok(payment2.ok);

  const result = statement('C-002', [payment1.value, payment2.value, issued3.value], '2026-12-31');
  assert.ok(result.ok);
  assert.equal(result.value.invoices.length, 2);
  assert.equal(result.value.invoices[0].due, 6495);
  assert.equal(result.value.invoices[1].due, 11495);
  assert.equal(result.value.totalDue, 17990);
});
